toad_implementation.code_blueprint:
canvas {
  size: 800px 800px;
  fill: #ECE9E2;
  font-family: "Plus Jakarta Sans, sans-serif";
}

>mossGreen = #3D4A3E;
>barkBrown = #8C7355;
>warmChalk = #ECE9E2;
>softOat = #DDD4C6;

circle #leafBackground {
  at: center of canvas offset 0px -30px;
  size: 260px;
  fill: >softOat;
}

rect #leafPillow {
  at: center of #leafBackground;
  size: 140px 140px;
  fill: >mossGreen;
  radius: 60px 0px 60px 0px;
}

circle #leafDewdrop {
  at: top right of #leafPillow offset -16px 16px;
  size: 24px;
  fill: >barkBrown;
}

text #brandTitle {
  at: below #leafBackground offset 52px;
  content: "S K O G";
  font-size: 26px;
  font-weight: 600;
  color: >mossGreen;
}

text #brandSubtitle {
  at: below #brandTitle offset 10px;
  content: "NORDIC BOTANICAL SANCTUARY";
  font-size: 11px;
  font-weight: 400;
  color: >barkBrown;
}
